const PriceChart = ({ user, onLoginRequired }) => {
  const { t } = useLanguage();
  const [commodities, setCommodities] = useState([]);
  const [cities, setCities] = useState([]);
  const [varieties, setVarieties] = useState([]);
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [chartType, setChartType] = useState("area");

  const [selectedCommodity, setSelectedCommodity] = useState("");
  const [selectedVariety, setSelectedVariety] = useState("");
  const [selectedCity, setSelectedCity] = useState("");
  const [days, setDays] = useState(30);
  const [selectedDate, setSelectedDate] = useState("");

  // Fetch initial data
  useEffect(() => {
    let isMounted = true;

    const fetchInitialData = async () => {
      try {
        const [commoditiesRes, citiesRes] = await Promise.all([
          fetch(`${API_URL}/prices/commodities`),
          fetch(`${API_URL}/prices/cities`),
        ]);

        const commoditiesData = await commoditiesRes.json();
        const citiesData = await citiesRes.json();

        if (!commoditiesRes.ok || !citiesRes.ok) {
          throw new Error("Failed to fetch price data");
        }

        if (isMounted) {
          const TARGET_COMMODITIES = ["Wheat", "Rice", "Cotton", "Sugar", "Maize", "Flour"];
          const commodityList = (commoditiesData.data || []).filter(c =>
            TARGET_COMMODITIES.includes(c)
          );
          const cityList = citiesData.data || [];

          setCommodities(commodityList);
          setCities(cityList);
          setSelectedCommodity(commodityList[0] || "");
          setSelectedCity(cityList[0] || "");
          setLoading(false);
        }
      } catch (err) {
        if (isMounted) {
          setError(err.message || "Failed to load price data");
          setLoading(false);
        }
      }
    };

    fetchInitialData();
    return () => { isMounted = false; };
  }, []);

  // Fetch varieties when commodity changes
  useEffect(() => {
    let isMounted = true;

    const fetchVarieties = async () => {
      if (!selectedCommodity) return;

      try {
        const response = await fetch(
          `${API_URL}/prices/varieties/${encodeURIComponent(selectedCommodity)}`
        );
        const responseData = await response.json();

        if (isMounted && response.ok) {
          const list = responseData.data || [];
          setVarieties(list);
          setSelectedVariety(list[0] || "");
        }
      } catch {
        if (isMounted) {
          setVarieties([]);
          setSelectedVariety("");
        }
      }
    };

    fetchVarieties();
    return () => { isMounted = false; };
  }, [selectedCommodity]);

  // Fetch cities based on commodity/variety
  useEffect(() => {
    let isMounted = true;

    const fetchCities = async () => {
      if (!selectedCommodity) return;

      try {
        const params = new URLSearchParams({ commodity: selectedCommodity });
        if (selectedVariety) params.set("variety", selectedVariety);

        const response = await fetch(
          `${API_URL}/prices/cities-by-filters?${params.toString()}`
        );
        const responseData = await response.json();

        if (isMounted && response.ok) {
          const list = responseData.data || [];
          setCities(list);
          if (!list.includes(selectedCity)) {
            setSelectedCity(list[0] || "");
          }
        }
      } catch {
        if (isMounted) {
          setCities([]);
          setSelectedCity("");
        }
      }
    };

    fetchCities();
    return () => { isMounted = false; };
  }, [selectedCommodity, selectedVariety, selectedCity]);

  // Fetch price history
  useEffect(() => {
    let isMounted = true;

    const fetchHistory = async () => {
      if (!selectedCommodity || !selectedCity) return;

      try {
        const params = new URLSearchParams({
          commodity: selectedCommodity,
          city: selectedCity,
        });

        if (selectedDate) {
          params.set("date", selectedDate);
        } else {
          params.set("days", days.toString());
        }

        if (selectedVariety) params.set("variety", selectedVariety);

        const response = await fetch(
          `${API_URL}/prices/history?${params.toString()}`
        );
        const responseData = await response.json();

        if (!response.ok) throw new Error(responseData.message);

        if (isMounted) {
          const mapped = (responseData.data || []).map((item) => ({
            date: new Date(item.date).toLocaleDateString("en-US", { month: "short", day: "numeric" }),
            price: item.price,
            unit: item.unit,
          }));

          setData(mapped);
          setError("");
        }
      } catch (err) {
        if (isMounted) {
          setData([]);
          setError(err.message || "Failed to load price data");
        }
      }
    };

    fetchHistory();
    return () => { isMounted = false; };
  }, [selectedCommodity, selectedCity, selectedVariety, days, selectedDate]);

  const handleProtectedAction = useCallback((action) => {
    if (!user && onLoginRequired) {
      onLoginRequired();
      return;
    }
    action();
  }, [user, onLoginRequired]);

  // Calculate statistics
  const prices = data.map(d => d.price).filter(Boolean);
  const latestPrice = prices[prices.length - 1] || 0;
  const firstPrice = prices[0] || 0;
  const highPrice = Math.max(...prices) || 0;
  const lowPrice = Math.min(...prices) || 0;
  const avgPrice = prices.length ? Math.round(prices.reduce((a, b) => a + b, 0) / prices.length) : 0;
  const priceChange = firstPrice ? ((latestPrice - firstPrice) / firstPrice * 100) : 0;
  const isPositive = priceChange > 0;
  const isNegative = priceChange < 0;

  const currentConfig = COMMODITY_CONFIG[selectedCommodity] || COMMODITY_CONFIG.Wheat;

  const displayUnit = data.length > 0 && data[data.length - 1]?.unit
    ? data[data.length - 1].unit.replace('Rs/', '').replace('(Maund)', 'Maund')
    : (selectedCommodity === 'Sugar' || selectedCommodity === 'Flour' ? 'Kg' : '40Kg Maund');

  const isEmpty = !loading && data.length === 0;

  // Render chart based on type
  const renderChart = () => {
    const isMobile = window.innerWidth < 640;
    const commonProps = {
      data,
      margin: { top: 10, right: isMobile ? 10 : 30, left: 5, bottom: 5 }
    };

    const xAxisProps = {
      dataKey: "date",
      tick: { fontSize: isMobile ? 10 : 13, fill: "#6b7280", fontWeight: 500 },
      tickFormatter: (value) => {
        // Shorter Format for Mobile (DD/MM) vs Full (MMM D)
        if (isMobile) {
          const parts = value.split(' '); // Assuming format like "Jan 12"
          return parts.length > 1 ? `${parts[1]}/${new Date(Date.parse(value + " 2024")).getMonth() + 1}` : value;
        }
        return value;
      },
      interval: data.length > (isMobile ? 8 : 14) ? Math.floor(data.length / (isMobile ? 4 : 5)) : 0,
      axisLine: false,
      tickLine: false,
      tickMargin: 8,
    };

    const yAxisProps = {
      tick: { fontSize: isMobile ? 10 : 13, fill: "#6b7280", fontWeight: 500 },
      tickFormatter: (value) => `₨${value.toLocaleString()}`,
      domain: ["auto", "auto"],
      axisLine: false,
      tickLine: false,
      width: isMobile ? 50 : 80,
    };

    switch (chartType) {
      case "line":
        return (
          <LineChart {...commonProps}>
            <defs>
              <linearGradient id="lineGradient" x1="0" y1="0" x2="1" y2="0">
                <stop offset="0%" stopColor="#059669" />
                <stop offset="100%" stopColor="#10b981" />
              </linearGradient>
            </defs>
            <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" vertical={false} />
            <XAxis {...xAxisProps} />
            <YAxis {...yAxisProps} />
            <Tooltip content={<CustomTooltip />} />
            <Line
              type="monotone"
              dataKey="price"
              stroke="url(#lineGradient)"
              strokeWidth={isMobile ? 2 : 2.5}
              dot={false}
              activeDot={{ r: 5, fill: "#059669", stroke: "#fff", strokeWidth: 2 }}
            />
          </LineChart>
        );

      case "bar":
        return (
          <BarChart {...commonProps}>
            <defs>
              <linearGradient id="barGradient" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor="#10b981" />
                <stop offset="100%" stopColor="#059669" />
              </linearGradient>
            </defs>
            <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" vertical={false} />
            <XAxis {...xAxisProps} />
            <YAxis {...yAxisProps} />
            <Tooltip content={<CustomTooltip />} />
            <Bar dataKey="price" fill="url(#barGradient)" radius={[4, 4, 0, 0]} />
          </BarChart>
        );

      default:
        return (
          <AreaChart {...commonProps}>
            <defs>
              <linearGradient id="areaGradient" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor="#10b981" stopOpacity={0.3} />
                <stop offset="100%" stopColor="#10b981" stopOpacity={0} />
              </linearGradient>
              <linearGradient id="areaStroke" x1="0" y1="0" x2="1" y2="0">
                <stop offset="0%" stopColor="#059669" />
                <stop offset="100%" stopColor="#10b981" />
              </linearGradient>
            </defs>
            <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" vertical={false} />
            <XAxis {...xAxisProps} />
            <YAxis {...yAxisProps} />
            <Tooltip content={<CustomTooltip />} />
            <Area
              type="monotone"
              dataKey="price"
              stroke="url(#areaStroke)"
              strokeWidth={isMobile ? 2 : 2.5}
              fill="url(#areaGradient)"
            />
          </AreaChart>
        );
    }
  };

  return (
    <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-lg border border-gray-200 dark:border-gray-700 overflow-hidden">
      {/* Header */}
      <div className="px-4 py-3 border-b border-gray-100 dark:border-gray-700 bg-gradient-to-r from-primary-50 to-emerald-50 dark:from-primary-900/20 dark:to-emerald-900/20">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-white dark:bg-gray-800 rounded-xl shadow-sm">
              <TrendingUp className="w-5 h-5 text-primary-600 dark:text-primary-400" />
            </div>
            <div>
              <h2 className="text-lg font-bold text-gray-900 dark:text-white">{t("priceChart.title")}</h2>
              <p className="text-xs text-gray-500 dark:text-gray-400">{t("priceChart.subtitle")}</p>
            </div>
          </div>
          <div className="flex items-center gap-3">
            {/* Chart Type Toggle */}
            <div className="flex items-center gap-0.5 p-1 bg-gray-100 dark:bg-gray-700 rounded-lg">
              {CHART_TYPES.map(({ type, icon, label }) => (
                <ChartTypeButton
                  key={type}
                  active={chartType === type}
                  onClick={() => setChartType(type)}
                  icon={icon}
                  label={label}
                />
              ))}
            </div>
            {/* Live Indicator */}
            <div className="hidden sm:flex items-center gap-1.5 px-2 py-1 bg-green-100 dark:bg-green-900/40 rounded-lg">
              <span className="relative flex h-2 w-2">
                <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-green-500 opacity-75"></span>
                <span className="relative inline-flex rounded-full h-2 w-2 bg-green-500"></span>
              </span>
              <span className="text-xs font-medium text-green-700 dark:text-green-400">Live</span>
            </div>
          </div>
        </div>
      </div>

      {loading ? (
        <div className="p-4">
          <ChartSkeleton />
        </div>
      ) : (
        <div className="p-4 space-y-4">
          {/* Commodity Selection */}
          <div className="flex gap-2 overflow-x-auto pb-1 -mx-1 px-1 scrollbar-hide">
            {commodities.map((commodity) => (
              <CommodityButton
                key={commodity}
                commodity={commodity}
                config={COMMODITY_CONFIG[commodity] || COMMODITY_CONFIG.Wheat}
                isSelected={selectedCommodity === commodity}
                onClick={() => setSelectedCommodity(commodity)}
              />
            ))}
          </div>

          {/* Filters Row */}
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
            {/* Variety Dropdown */}
            {varieties.length > 0 && (
              <DropdownSelect
                label={t("priceChart.variety")}
                icon={Leaf}
                value={selectedVariety}
                options={varieties}
                onChange={(v) => handleProtectedAction(() => setSelectedVariety(v))}
              />
            )}

            {/* City Dropdown */}
            <DropdownSelect
              label={t("priceChart.city")}
              icon={MapPin}
              value={selectedCity}
              options={cities}
              onChange={(c) => handleProtectedAction(() => setSelectedCity(c))}
            />

          </div>

          {/* Date and Period Selection */}
          <div className="flex flex-col sm:flex-row sm:items-end gap-2">
            {/* Date Picker */}
            <div className="w-full sm:w-auto">
              <p className="text-sm text-gray-500 dark:text-gray-400 mb-1.5 ml-1">{t("priceChart.date")}</p>
              <div className="relative">
                <input
                  type="date"
                  value={selectedDate}
                  max={new Date().toISOString().split('T')[0]}
                  onChange={(e) => handleProtectedAction(() => {
                    setSelectedDate(e.target.value);
                    setDays(30); // Reset or keep default, visually it will depend on selectedDate being truthy
                  })}
                  className={`
                    w-full h-[42px] px-3 py-2 pl-10 rounded-lg
                    bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-200
                    border-0
                    focus:ring-2 focus:ring-primary-500 dark:focus:ring-primary-400
                    outline-none transition-all duration-200
                    [color-scheme:light] dark:[color-scheme:dark]
                    [&::-webkit-calendar-picker-indicator]:dark:invert
                    [&::-webkit-calendar-picker-indicator]:opacity-60
                    [&::-webkit-calendar-picker-indicator]:hover:opacity-100
                    [&::-webkit-calendar-picker-indicator]:cursor-pointer
                    ${selectedDate ? "ring-2 ring-primary-500 dark:ring-primary-400 font-semibold bg-primary-50 dark:bg-primary-900/30" : ""}
                  `}
                />
                <Calendar className={`
                  absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 pointer-events-none
                  ${selectedDate ? "text-primary-600 dark:text-primary-400" : "text-gray-400 dark:text-gray-500"}
                `} />
              </div>
            </div>

            {/* Time Period */}
            <div className="flex-1">
              <p className="text-sm text-gray-500 dark:text-gray-400 mb-1.5 ml-1">{t("priceChart.period")}</p>
              <div className="flex gap-1">
                {TIME_PERIODS.map((period) => (
                  <button
                    key={period.value}
                    onClick={() => handleProtectedAction(() => {
                      setDays(period.value);
                      setSelectedDate(""); // Clear date when period is selected
                    })}
                    className={`
                      flex-1 h-[42px] px-2 rounded-lg text-sm font-bold transition-all duration-200
                      ${(days === period.value && !selectedDate)
                        ? "bg-primary-600 text-white shadow-md"
                        : "bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-gray-600"
                      }
                    `}
                  >
                    {period.label}
                  </button>
                ))}
              </div>
            </div>
          </div>

          {/* Price Display */}
          <div className="bg-gradient-to-r from-primary-50 to-emerald-50 dark:from-primary-900/20 dark:to-emerald-900/20 rounded-xl p-4 border border-primary-100 dark:border-primary-800/30">
            <div className="flex flex-wrap items-center justify-between gap-3">
              <div className="flex items-center gap-3">
                <div className={`p-2 rounded-lg ${currentConfig.bg}`}>
                  {currentConfig.image ? (
                    <img src={currentConfig.image} alt={selectedCommodity} className="w-12 h-12 object-contain" />
                  ) : (
                    <span className="text-2xl">{currentConfig.emoji}</span>
                  )}
                </div>
                <div>
                  <p className="text-xs text-gray-500 dark:text-gray-400">
                    {selectedCommodity} {selectedVariety && `• ${selectedVariety}`} • {selectedCity}
                  </p>
                  <div className="flex items-baseline gap-2">
                    <span className="text-3xl font-bold text-gray-900 dark:text-white">
                      ₨{latestPrice.toLocaleString()}
                    </span>
                    <span className="text-sm text-gray-500 dark:text-gray-400">/{displayUnit}</span>
                  </div>
                </div>
              </div>

              {latestPrice > 0 && (
                <div className={`
                  flex items-center gap-2 px-3 py-2 rounded-xl
                  ${isPositive ? "bg-green-100 dark:bg-green-900/50" : isNegative ? "bg-red-100 dark:bg-red-900/50" : "bg-gray-100 dark:bg-gray-700"}
                `}>
                  {isPositive ? (
                    <TrendingUp className="w-5 h-5 text-green-600 dark:text-green-400" />
                  ) : isNegative ? (
                    <TrendingDown className="w-5 h-5 text-red-600 dark:text-red-400" />
                  ) : (
                    <Minus className="w-5 h-5 text-gray-500" />
                  )}
                  <div>
                    <p className={`text-lg font-bold ${isPositive ? "text-green-700 dark:text-green-400" : isNegative ? "text-red-700 dark:text-red-400" : "text-gray-600"
                      }`}>
                      {isPositive ? "+" : ""}{priceChange.toFixed(1)}%
                    </p>
                  </div>
                </div>
              )}
            </div>
          </div>

          {/* Stats Cards */}
          <div className="grid grid-cols-3 gap-2">
            <PriceStatsCard
              label={t("priceChart.high")}
              value={highPrice}
              unit={displayUnit}
              icon={TrendingUp}
              color="bg-green-50 dark:bg-green-900/30 text-green-700 dark:text-green-300"
            />
            <PriceStatsCard
              label={t("priceChart.avg")}
              value={avgPrice}
              unit={displayUnit}
              icon={Minus}
              color="bg-blue-50 dark:bg-blue-900/30 text-blue-700 dark:text-blue-300"
            />
            <PriceStatsCard
              label={t("priceChart.low")}
              value={lowPrice}
              unit={displayUnit}
              icon={TrendingDown}
              color="bg-amber-50 dark:bg-amber-900/30 text-amber-700 dark:text-amber-300"
            />
          </div>

          {/* Chart */}
          <div className="bg-gray-50 dark:bg-gray-900/50 rounded-xl p-3">
            <div className="w-full h-64">
              {error || isEmpty ? (
                <div className="h-full flex flex-col items-center justify-center text-gray-500 dark:text-gray-400">
                  <div className="text-4xl mb-3">📊</div>
                  <p className="text-sm font-medium mb-1">{t("priceChart.noData")}</p>
                  <p className="text-xs text-center max-w-xs mb-3">
                    {error || t("priceChart.noDataDesc")}
                  </p>
                  <button
                    onClick={() => window.location.reload()}
                    className="flex items-center gap-1.5 px-3 py-1.5 bg-primary-100 dark:bg-primary-900/40 text-primary-700 dark:text-primary-300 rounded-lg text-sm font-medium hover:bg-primary-200 dark:hover:bg-primary-900/60 transition-colors"
                  >
                    <RefreshCw className="w-3.5 h-3.5" />
                    {t("priceChart.refresh")}
                  </button>
                </div>
              ) : (
                <ResponsiveContainer width="100%" height="100%">
                  {renderChart()}
                </ResponsiveContainer>
              )}
            </div>
          </div>

          {/* Footer */}
          <div className="flex items-center justify-between text-xs text-gray-400 dark:text-gray-500">
            <p>{t("priceChart.source")}</p>
            <p>{t("priceChart.updatedHourly")}</p>
          </div>
        </div>
      )}
    </div>
  );
};

export default memo(PriceChart);

import React, { useEffect, useState } from "react";
import { TrendingUp, TrendingDown, Minus } from "lucide-react";
import API_URL from "../config";

const PriceTicker = ({ prices = [] }) => {
  const [livePrices, setLivePrices] = useState([]);
  const [isPaused, setIsPaused] = useState(false);

  // Default sample data if no prices provided
  const defaultPrices = [
    { commodity: "Wheat", price: 4200, change: 2.3, unit: "100kg" },
    { commodity: "Rice (Basmati)", price: 8500, change: -1.1, unit: "100kg" },
    { commodity: "Maize", price: 2800, change: 0.8, unit: "100kg" },
    { commodity: "Cotton", price: 15200, change: 3.5, unit: "40kg" },
    { commodity: "Sugarcane", price: 350, change: -0.5, unit: "40kg" },
    { commodity: "Rice (IRRI)", price: 5200, change: 1.2, unit: "100kg" },
  ];

  useEffect(() => {
    let isMounted = true;

    // Try to load from cache first for instant mobile feel
    const cachedData = sessionStorage.getItem("ticker_prices_cache");
    if (cachedData) {
      try {
        setLivePrices(JSON.parse(cachedData));
        setIsLoading(false);
      } catch (e) {
        console.error("Cache parse error:", e);
      }
    }

    const fetchPrices = async () => {
      try {
        const response = await fetch(`${API_URL}/prices/latest`, {
          credentials: 'include'
        });
        const data = await response.json();

        if (!response.ok) {
          throw new Error(data.message || "Failed to fetch prices");
        }

        if (isMounted) {
          const TARGET_COMMODITIES = ["Wheat", "Rice", "Cotton", "Sugar", "Maize", "Flour"];
          const mapped = (data.data || [])
            .filter(item => TARGET_COMMODITIES.includes(item.commodity))
            .map((item) => {
              // Clean up unit display
              let displayUnit = item.unit || "40Kg";
              if (displayUnit.startsWith("Rs/")) {
                displayUnit = displayUnit.substring(3);
              }

              return {
                commodity: item.variety ? `${item.commodity} (${item.variety})` : item.commodity,
                city: item.city,
                price: item.price,
                unit: displayUnit,
                change: item.change, // Include price change from API
              };
            });
          if (mapped.length > 0) {
            setLivePrices(mapped);
            // Update cache
            sessionStorage.setItem("ticker_prices_cache", JSON.stringify(mapped));
          }
        }
      } catch (error) {
        console.error("Price ticker fetch error:", error);
      }
    };

    fetchPrices();
    return () => {
      isMounted = false;
    };
  }, []);

  // Always show data - use live prices if available, otherwise default
  const tickerData = prices.length > 0 ? prices : livePrices.length > 0 ? livePrices : defaultPrices;

  // Double the data for seamless infinite scroll
  const doubledData = [...tickerData, ...tickerData];

  return (
    <div
      className="w-full bg-primary-50 dark:bg-gray-950 border-b border-primary-100 dark:border-gray-800 overflow-hidden cursor-pointer"
      onMouseEnter={() => setIsPaused(true)}
      onMouseLeave={() => setIsPaused(false)}
    >
      <div className="relative flex items-center h-10 overflow-hidden">
        {/* Gradient masks for smooth edges */}
        <div className="absolute left-0 top-0 bottom-0 w-12 bg-gradient-to-r from-primary-50 dark:from-gray-950 to-transparent z-10 pointer-events-none" />
        <div className="absolute right-0 top-0 bottom-0 w-12 bg-gradient-to-l from-primary-50 dark:from-gray-950 to-transparent z-10 pointer-events-none" />

        {/* Scrolling content */}
        <div
          className="flex whitespace-nowrap animate-ticker will-change-transform"
          style={{
            animation: 'ticker 120s linear infinite',
            animationPlayState: isPaused ? 'paused' : 'running',
          }}
        >
          {doubledData.map((item, index) => (
            <div
              key={`${item.commodity}-${item.city || 'default'}-${index}`}
              className="inline-flex items-center gap-2 px-4 border-r border-primary-200 dark:border-gray-700/50 flex-shrink-0"
            >
              <span className="text-gray-600 dark:text-gray-400 font-medium text-sm">
                {item.commodity}
              </span>
              {item.city && (
                <span className="text-gray-500 dark:text-gray-500 text-xs">
                  @ {item.city}
                </span>
              )}
              <span className="text-gray-900 dark:text-white font-semibold text-sm">
                ₨{item.price?.toLocaleString() || '0'}
              </span>
              {typeof item.change === "number" && (
                <span
                  className={`flex items-center gap-0.5 text-xs font-medium ${item.change >= 0 ? "text-green-600 dark:text-green-400" : "text-red-600 dark:text-red-400"
                    }`}
                >
                  {item.change >= 0 ? (
                    <TrendingUp className="w-3 h-3" />
                  ) : (
                    <TrendingDown className="w-3 h-3" />
                  )}
                  {Math.abs(item.change)}%
                </span>
              )}
              <span className="text-gray-500 dark:text-gray-500 text-xs">/{item.unit}</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default PriceTicker;

import React, { useEffect, useState } from "react";
import { 
  Package, 
  MessageCircle, 
  TrendingUp, 
  Bell,
  ArrowUpRight,
  ArrowDownRight,
  Minus
} from "lucide-react";
import API_URL from "../config";
import { useNavigate } from "react-router-dom";
import { useNotifications } from "../contexts/NotificationContext";
import { alertsAPI } from "../utils/api";
import axios from "axios";

const StatCard = ({ 
  title, 
  value, 
  subtitle, 
  icon: Icon, 
  trend, 
  trendLabel,
  color,
  onClick,
  delay = 0
}) => {
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => setIsVisible(true), delay);
    return () => clearTimeout(timer);
  }, [delay]);

  const getTrendIcon = () => {
    if (trend > 0) return <ArrowUpRight className="w-4 h-4" />;
    if (trend < 0) return <ArrowDownRight className="w-4 h-4" />;
    return <Minus className="w-4 h-4" />;
  };

  const getTrendColor = () => {
    if (trend > 0) return "text-green-600 dark:text-green-400 bg-green-100 dark:bg-green-900/30";
    if (trend < 0) return "text-red-600 dark:text-red-400 bg-red-100 dark:bg-red-900/30";
    return "text-gray-600 dark:text-gray-400 bg-gray-100 dark:bg-gray-700";
  };

  const colorStyles = {
    emerald: "bg-emerald-100 dark:bg-emerald-900/30 text-emerald-600 dark:text-emerald-400",
    blue: "bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400",
    purple: "bg-purple-100 dark:bg-purple-900/30 text-purple-600 dark:text-purple-400",
    amber: "bg-amber-100 dark:bg-amber-900/30 text-amber-600 dark:text-amber-400",
  };

  return (
    <div 
      onClick={onClick}
      className={`
        relative bg-white dark:bg-gray-800 rounded-2xl p-5 border border-gray-200 dark:border-gray-700
        shadow-sm hover:shadow-lg transition-all duration-300 
        ${onClick ? 'cursor-pointer hover:-translate-y-1' : ''}
        ${isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4'}
      `}
      style={{ transitionDelay: `${delay}ms` }}
    >
      {/* Icon */}
      <div className={`inline-flex p-3 rounded-xl ${colorStyles[color]} mb-4`}>
        <Icon className="w-6 h-6" />
      </div>

      {/* Value */}
      <div className="mb-1">
        <span className="text-3xl font-bold text-gray-900 dark:text-white">
          {value}
        </span>
      </div>

      {/* Title */}
      <p className="text-gray-600 dark:text-gray-400 font-medium mb-2">
        {title}
      </p>

      {/* Trend or Subtitle */}
      {trend !== undefined ? (
        <div className={`inline-flex items-center gap-1 px-2 py-1 rounded-full text-xs font-medium ${getTrendColor()}`}>
          {getTrendIcon()}
          <span>{Math.abs(trend)}%</span>
          {trendLabel && <span className="text-gray-500 dark:text-gray-400 ml-1">{trendLabel}</span>}
        </div>
      ) : subtitle ? (
        <p className="text-sm text-gray-500 dark:text-gray-500">{subtitle}</p>
      ) : null}

      {/* Decorative gradient */}
      <div className="absolute top-0 right-0 w-24 h-24 opacity-5 pointer-events-none">
        <div className={`w-full h-full rounded-full bg-gradient-to-br ${
          color === 'emerald' ? 'from-emerald-500' :
          color === 'blue' ? 'from-blue-500' :
          color === 'purple' ? 'from-purple-500' :
          'from-amber-500'
        } to-transparent blur-2xl`} />
      </div>
    </div>
  );
};

const QuickStatsGrid = ({ user, unreadCount = 0 }) => {
  const navigate = useNavigate();
  const { triggeredAlerts } = useNotifications();
  const [stats, setStats] = useState({
    activeListings: 0,
    messages: unreadCount,
    marketTrend: 0,
    alerts: 0,
    loading: true,
  });

  // Fetch real stats from backend
  useEffect(() => {
    const fetchStats = async () => {
      let activeAlerts = 0;
      let activeListings = 0;
      let marketTrend = 0;

      // Fetch user-specific stats only if logged in
      if (user) {
        try {
          // Fetch alert statistics
          try {
            const alertStatsRes = await alertsAPI.getStats();
            activeAlerts = alertStatsRes?.data?.active || 0;
          } catch (err) {
            console.error("Error fetching alert stats:", err);
          }

          // Fetch listings count - only active status
          try {
            const listingsRes = await axios.get(`${API_URL}/listings/my/listings?status=active`, {
              withCredentials: true,
            });
            const total = listingsRes?.data?.pagination?.total || 0;
            activeListings = total;
          } catch (err) {
            console.error("Error fetching listings:", err);
          }
        } catch (error) {
          console.error("Error fetching user stats:", error);
        }
      }

      // Always fetch market trend (public data)
      try {
        // Get all latest prices (one per commodity/city combination)
        const latestRes = await axios.get(`${API_URL}/prices/latest?limit=100`, {
          withCredentials: true,
        });

        const latestData = latestRes?.data?.data || latestRes?.data || [];

        if (Array.isArray(latestData) && latestData.length > 0) {
          // Get diverse samples from different cities and commodities
          const seenKeys = new Set();
          const samples = [];

          for (const item of latestData) {
            // Unique by commodity-city-variety combination
            const key = `${item.commodity}-${item.city}-${item.variety || 'null'}`;
            if (!seenKeys.has(key)) {
              samples.push(item);
              seenKeys.add(key);
              if (samples.length >= 25) break;
            }
          }

          // Fetch all price histories in parallel (30 days for better trend detection)
          const historyPromises = samples.map(sample => {
            let url = `${API_URL}/prices/history?commodity=${encodeURIComponent(sample.commodity)}&city=${encodeURIComponent(sample.city)}&days=30`;
            if (sample.variety !== null && sample.variety !== undefined) {
              url += `&variety=${encodeURIComponent(sample.variety)}`;
            }
            return axios.get(url, { withCredentials: true }).catch(() => null);
          });

          const historyResults = await Promise.all(historyPromises);

          const trends = [];

          historyResults.forEach((result) => {
            if (!result) return;

            const prices = result?.data?.data || result?.data || [];

            if (Array.isArray(prices) && prices.length >= 2) {
              // Sort by date (oldest first)
              const sortedPrices = [...prices].sort((a, b) => new Date(a.date) - new Date(b.date));

              // Get oldest and newest price
              const oldestPrice = sortedPrices[0]?.price || 0;
              const newestPrice = sortedPrices[sortedPrices.length - 1]?.price || 0;

              if (oldestPrice > 0 && newestPrice > 0 && oldestPrice !== newestPrice) {
                const trend = ((newestPrice - oldestPrice) / oldestPrice) * 100;
                trends.push(trend);
              }
            }
          });

          // Calculate average trend
          if (trends.length > 0) {
            marketTrend = trends.reduce((sum, t) => sum + t, 0) / trends.length;
            marketTrend = parseFloat(marketTrend.toFixed(1));
          }
        }
      } catch (err) {
        console.error("Error fetching price trend:", err.response?.data || err.message);
      }

      setStats({
        activeListings,
        messages: unreadCount,
        marketTrend,
        alerts: activeAlerts,
        loading: false,
      });
    };

    fetchStats();
  }, [user, unreadCount, triggeredAlerts?.length]); // Re-fetch when alerts change

  const cards = [
    {
      title: "Active Listings",
      value: user ? (stats.loading ? "..." : stats.activeListings) : "--",
      subtitle: user ? "View your listings" : "Sign in to view",
      icon: Package,
      color: "emerald",
      onClick: () => navigate("/my-listings"),
    },
    {
      title: "Unread Messages",
      value: user ? stats.messages : "--",
      subtitle: user ? (stats.messages > 0 ? "New messages waiting" : "All caught up!") : "Sign in to chat",
      icon: MessageCircle,
      color: "blue",
      onClick: () => navigate("/chat"),
    },
    {
      title: "Market Trend",
      value: stats.loading ? "..." : (stats.marketTrend === 0 ? "Stable" : `${stats.marketTrend > 0 ? '+' : ''}${stats.marketTrend}%`),
      trend: stats.marketTrend,
      trendLabel: stats.marketTrend === 0 ? "no change" : "this month",
      icon: TrendingUp,
      color: "purple",
      onClick: null,
    },
    {
      title: "Price Alerts",
      value: user ? (stats.loading ? "..." : stats.alerts) : "--",
      subtitle: user ? "Active alerts" : "Sign in to set alerts",
      icon: Bell,
      color: "amber",
      onClick: user ? null : () => navigate("/signin"),
    },
  ];

  return (
    <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
      {cards.map((card, index) => (
        <StatCard
          key={card.title}
          {...card}
          delay={index * 100}
        />
      ))}
    </div>
  );
};

export default QuickStatsGrid;

import { useState } from "react";

export default function ReviewModal({ isOpen, onClose, onSubmit, transaction, darkMode }) {
  const [rating, setRating] = useState(5);
  const [comment, setComment] = useState("");
  const [hoveredRating, setHoveredRating] = useState(0);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const sessionUser = JSON.parse(sessionStorage.getItem("user") || "{}");
  const currentUserId = sessionUser?._id || sessionUser?.id;
  const isBuyer = transaction?.buyer?._id?.toString() === currentUserId?.toString();
  const otherUser = isBuyer ? transaction?.seller : transaction?.buyer;

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    setLoading(true);

    try {
      await onSubmit(rating, comment);
      setRating(5);
      setComment("");
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
      <div className="w-full max-w-md rounded-2xl shadow-xl bg-white dark:bg-gray-800">
        <div className="p-6">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-xl font-bold text-gray-900 dark:text-white">
              Rate Your Experience
            </h2>
            <button
              onClick={onClose}
              className="p-2 rounded-full hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-500 dark:text-gray-400"
            >
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          </div>

          {/* User being rated */}
          <div className="flex items-center gap-3 p-3 rounded-lg mb-6 bg-gray-50 dark:bg-gray-700">
            <div className="w-12 h-12 rounded-full overflow-hidden bg-gray-300 flex-shrink-0">
              {otherUser?.avatar ? (
                <img
                  src={otherUser.avatar}
                  alt={otherUser.name}
                  className="w-full h-full object-cover"
                />
              ) : (
                <div className="w-full h-full flex items-center justify-center text-gray-500 font-semibold text-lg">
                  {otherUser?.name?.charAt(0) || "?"}
                </div>
              )}
            </div>
            <div>
              <p className="font-medium text-gray-900 dark:text-white">
                {otherUser?.name || "User"}
              </p>
              <p className="text-sm text-gray-500 dark:text-gray-400">
                {isBuyer ? "Seller" : "Buyer"}
              </p>
            </div>
          </div>

          <form onSubmit={handleSubmit}>
            {/* Star Rating */}
            <div className="mb-6">
              <label className="block text-sm font-medium mb-2 text-gray-700 dark:text-gray-300">
                Rating
              </label>
              <div className="flex justify-center gap-1">
                {[1, 2, 3, 4, 5].map((star) => (
                  <button
                    key={star}
                    type="button"
                    onClick={() => setRating(star)}
                    onMouseEnter={() => setHoveredRating(star)}
                    onMouseLeave={() => setHoveredRating(0)}
                    className="p-1 focus:outline-none transform transition-transform hover:scale-110"
                  >
                    <svg
                      className={`w-10 h-10 ${star <= (hoveredRating || rating)
                          ? "text-yellow-400"
                          : "text-gray-300 dark:text-gray-600"
                        }`}
                      fill="currentColor"
                      viewBox="0 0 20 20"
                    >
                      <path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z" />
                    </svg>
                  </button>
                ))}
              </div>
              <p className="text-center mt-2 text-sm text-gray-500 dark:text-gray-400">
                {rating === 1 && "Poor"}
                {rating === 2 && "Fair"}
                {rating === 3 && "Good"}
                {rating === 4 && "Very Good"}
                {rating === 5 && "Excellent"}
              </p>
            </div>

            {/* Comment */}
            <div className="mb-6">
              <label className="block text-sm font-medium mb-2 text-gray-700 dark:text-gray-300">
                Comment (Optional)
              </label>
              <textarea
                value={comment}
                onChange={(e) => setComment(e.target.value)}
                maxLength={500}
                rows={3}
                placeholder="Share your experience..."
                className="w-full px-4 py-3 rounded-lg border bg-white dark:bg-gray-700 border-gray-300 dark:border-gray-600 text-gray-900 dark:text-white placeholder-gray-500 dark:placeholder-gray-400 focus:ring-2 focus:ring-green-500 focus:border-transparent"
              />
              <p className="text-right text-xs mt-1 text-gray-400 dark:text-gray-500">
                {comment.length}/500
              </p>
            </div>

            {error && (
              <div className="mb-4 p-3 bg-red-100 text-red-700 rounded-lg text-sm">
                {error}
              </div>
            )}

            {/* Submit Button */}
            <div className="flex gap-3">
              <button
                type="button"
                onClick={onClose}
                className="flex-1 py-3 rounded-lg font-medium bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-600"
              >
                Cancel
              </button>
              <button
                type="submit"
                disabled={loading}
                className="flex-1 py-3 bg-green-600 text-white rounded-lg font-medium hover:bg-green-700 disabled:opacity-50"
              >
                {loading ? "Submitting..." : "Submit Review"}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
}
